/**
 * Every Sprout message in Epic 5 is written in advance and chosen by the
 * user's current selections - never generated by a model (Definition of
 * Done: "No AI model is used"). This file is the full set of message banks,
 * kept as pure functions so the wizard components stay about layout, not copy.
 */
import type { Preferences } from '@/types/personalisation'
import type { PersonalisedRoute } from '@/types/personalisation'

export type Mood = 'calm' | 'okay' | 'tense' | 'stressed' | 'overwhelmed'

export const MOOD_OPTIONS: { value: Mood; label: string }[] = [
  { value: 'calm', label: 'Calm' },
  { value: 'okay', label: 'Okay' },
  { value: 'tense', label: 'A bit tense' },
  { value: 'stressed', label: 'Stressed' },
  { value: 'overwhelmed', label: 'Overwhelmed' },
]

const MOOD_REPLIES: Record<Mood, string> = {
  calm: 'Love that. Let’s keep the good vibes going.',
  okay: 'Nice. A walk under some leaves will keep it that way.',
  tense: 'Thanks for telling me. We’ll take it gently.',
  stressed: 'That sounds heavy. I’ll pick quieter, shadier paths for you.',
  overwhelmed: 'I’m really glad you’re here. Let’s go slow, one step at a time.',
}

export function moodReply(mood: Mood): string {
  return MOOD_REPLIES[mood]
}

/** US5.2: picking Stressed or Overwhelmed preselects the calmest options. */
export function moodNeedsCalmPreset(mood: Mood | null): boolean {
  return mood === 'stressed' || mood === 'overwhelmed'
}

export type CanopyChoice = 'open' | 'mixed' | 'dense'
export const CANOPY_OPTIONS: { value: CanopyChoice; label: string; sliderValue: number }[] = [
  { value: 'open', label: 'Open sky', sliderValue: 10 },
  { value: 'mixed', label: 'A bit of both', sliderValue: 50 },
  { value: 'dense', label: 'Deep canopy', sliderValue: 100 },
]
const CANOPY_REPLIES: Record<CanopyChoice, string> = {
  open: 'Open skies it is! Just me and a bit of sunshine.',
  mixed: 'A few of my friends are coming along.',
  dense: 'Yay, the whole gang is coming!',
}
export function canopyReply(choice: CanopyChoice): string {
  return CANOPY_REPLIES[choice]
}
export function canopyFromSlider(value: number | null): CanopyChoice | null {
  if (value === null) return null
  if (value >= 75) return 'dense'
  if (value >= 35) return 'mixed'
  return 'open'
}

export type ThermalChoice = 'sunny' | 'mixed' | 'cool'
export const THERMAL_OPTIONS: { value: ThermalChoice; label: string; sliderValue: number }[] = [
  { value: 'sunny', label: 'Sunny and open', sliderValue: 10 },
  { value: 'mixed', label: 'A bit of both', sliderValue: 50 },
  { value: 'cool', label: 'Cool and shaded', sliderValue: 100 },
]
const THERMAL_REPLIES: Record<ThermalChoice, string> = {
  sunny: 'Bring water! I’m thirsty just thinking about it.',
  mixed: 'Good balance. I’ll mix sunny streets with shady stretches.',
  cool: 'Ahh. My canopy has you covered.',
}
export function thermalReply(choice: ThermalChoice): string {
  return THERMAL_REPLIES[choice]
}
export function thermalFromSlider(value: number | null): ThermalChoice | null {
  if (value === null) return null
  if (value >= 75) return 'cool'
  if (value >= 35) return 'mixed'
  return 'sunny'
}

/** US5.3: the shade step's opening line depends on the live CBD temperature band. */
export function temperaturePrompt(temperatureCelsius: number | null): string {
  if (temperatureCelsius === null) return 'Sun or shade?'
  if (temperatureCelsius >= 25) return 'It’s warm in the city today. Sun or shade?'
  if (temperatureCelsius >= 18) return 'It’s a mild day in the city. Sun or shade?'
  return 'It’s a cool day in the city. Sun or shade?'
}

export function noiseReply(value: Preferences['noise']): string | null {
  if (value === 'quiet') return 'Quiet streets it is. Just a peaceful rustle.'
  if (value === 'lively') return 'Noted - I’ll keep you closer to the busier streets.'
  return null
}

export function allergyReply(value: Preferences['allergy']): string | null {
  if (value === 'avoid') return 'Got it. I’ll steer you around the heavy pollen trees.'
  if (value === 'lower') return 'Got it, I’ll lean towards the lower-pollen trees where I can.'
  return null
}

export const AUTO_PRESET_NOTE =
  'Since you’re feeling stressed, I picked the calmest options for you. Change anything you like!'

export function greeting(): { title: string; body: string } {
  return {
    title: 'Hi, I’m Sprout!',
    body: 'A few quick questions and I’ll grow you a calmer, greener walk.',
  }
}

export function placeChosenReply(label: string): string {
  return `Got it, ${label}. Ready when you are!`
}

export const OUTSIDE_CBD_REPLY =
  'That’s outside the CBD, so I don’t know the trees there yet - pick a start point inside the dashed area.'

export const DEFAULT_MAP_REPLY =
  'Tap a starting point. I only know the trees inside the dashed CBD area for now.'

/**
 * US5.6: Sprout's route explanation. Reuses the backend's own matched/missed
 * reasoning (`route.match.sentence`, already built from the same preference
 * flags - see backend/app/routers/routes.py `_sentence()`) rather than
 * re-deriving it, so Sprout never claims a match the scorer didn't find.
 * Always pairs it with a concrete route fact (walk time or canopy share).
 */
export function routeExplanation(route: PersonalisedRoute): string {
  const fact =
    route.metrics?.canopy != null
      ? `about ${Math.round(route.metrics.canopy)}% of the area around it is tree canopy`
      : `it’s a ${route.durationMinutes} minute walk`
  const reasoning = route.match?.sentence ?? 'Here’s the walk I found for you.'
  return `${reasoning} Along the way, ${fact}.`
}
